@import url('https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&family=Gowun+Batang:wght@400;700&family=Marcellus&display=swap');
:root{--ink:#f1eee8;--muted:#989aa8;--faint:#696d7c;--gold:#d8b979;--gold-bright:#f0d99c;--violet:#a69ce0;--panel:rgba(25,28,39,.84);--line:rgba(214,198,160,.13);--serif:'Gowun Batang',serif;--sans:'DM Sans','Apple SD Gothic Neo',sans-serif}*{box-sizing:border-box}body{margin:0;min-height:100vh;background:#10131c;color:var(--ink);font-family:var(--sans);font-size:14px;overflow-x:hidden}.ambient{position:fixed;z-index:-1;pointer-events:none;border-radius:50%;filter:blur(100px);opacity:.12}.ambient-one{width:420px;height:420px;background:#7369c5;top:-180px;right:9%}.ambient-two{width:360px;height:360px;background:#b98c52;bottom:-210px;left:20%}.topbar{height:76px;border-bottom:1px solid rgba(255,255,255,.07);display:flex;align-items:center;justify-content:space-between;padding:0 6.1%;position:relative;z-index:2;background:rgba(13,16,24,.46)}.brand{text-decoration:none;color:var(--ink);display:flex;align-items:center;gap:12px;font-family:var(--serif);font-size:18px;letter-spacing:.03em}.brand-mark{color:var(--gold);font-size:24px}.brand small{display:block;color:#777b89;font:9px var(--sans);letter-spacing:.2em;margin-top:3px}.top-actions{display:flex;align-items:center;gap:18px}.chapter-label{font-size:11px;color:#b9b6ad;letter-spacing:.06em;margin-right:10px}.chapter-label i,.status-dot{display:inline-block;width:6px;height:6px;background:#8eb593;border-radius:50%;margin-right:8px;box-shadow:0 0 9px #8eb593}.icon-button{width:32px;height:32px;border:1px solid rgba(255,255,255,.1);border-radius:50%;background:transparent;color:#a8a8b0;cursor:pointer;transition:.2s}.icon-button:hover,.icon-button.active{border-color:var(--gold);color:var(--gold)}main{width:100%;max-width:1510px;margin:0 auto;padding:0 5.3%}.title-screen{min-height:calc(100vh - 76px);display:grid;grid-template-columns:1.04fr .96fr;align-items:center;gap:8%;padding:35px 2% 55px}.title-art{height:min(590px,72vh);min-height:440px;position:relative;overflow:hidden;border:1px solid rgba(220,201,156,.16);background:radial-gradient(ellipse at 51% 37%,#393a59 0,#222638 25%,#151b2a 56%,#131720 78%);box-shadow:0 30px 80px #080a10}.title-art:before,.scene-art:before{content:'';position:absolute;inset:0;background:linear-gradient(180deg,transparent 58%,rgba(13,16,23,.84)),repeating-linear-gradient(90deg,transparent 0 80px,rgba(255,255,255,.012) 81px 82px)}.moon{position:absolute;width:168px;height:168px;border-radius:50%;background:radial-gradient(circle at 38% 36%,#fff5cf,#d5c79e 48%,#988b82 72%,#635e68);box-shadow:0 0 38px #ebd69c66,0 0 110px #a5a9e055;top:17%;left:44%}.moon:after{content:'';position:absolute;width:168px;height:168px;background:#202333;border-radius:50%;left:17px;top:-10px;opacity:.33}.art-stars{position:absolute;top:13%;left:15%;width:75%;text-align:center;color:#e3d4aa;letter-spacing:20px;opacity:.72;font-size:15px}.mountain{position:absolute;bottom:0;left:-10%;width:120%;height:45%;background:#151c2a;clip-path:polygon(0 60%,13% 41%,23% 60%,39% 17%,50% 56%,62% 35%,75% 62%,90% 29%,100% 55%,100% 100%,0 100%)}.mountain-back{height:34%;bottom:22%;background:#272c40;opacity:.72;clip-path:polygon(0 67%,14% 30%,27% 62%,47% 10%,63% 70%,80% 34%,100% 64%,100% 100%,0 100%)}.mountain-front{height:31%;background:#11151f;clip-path:polygon(0 39%,20% 58%,37% 30%,60% 65%,82% 25%,100% 46%,100% 100%,0 100%)}.hero-silhouette{position:absolute;bottom:9%;left:48%;height:145px;width:62px;background:#0d1017;clip-path:polygon(45% 0,58% 0,66% 13%,82% 19%,76% 34%,68% 32%,74% 52%,90% 72%,100% 100%,0 100%,17% 72%,33% 53%,34% 34%,22% 30%,28% 18%,41% 13%);filter:drop-shadow(0 0 16px #080a10)}.hero-silhouette:before{content:'';position:absolute;left:28px;top:70px;width:100px;height:2px;background:#c9b57d;transform:rotate(-30deg);box-shadow:0 0 9px #efd28c}.title-copy{padding:10px 0 10px 5px}.eyebrow{font-size:10px;letter-spacing:.24em;color:var(--gold);font-weight:600;margin:0 0 23px}.title-copy h1{font:400 clamp(54px,7vw,86px)/1.08 var(--serif);letter-spacing:-.08em;margin:0 0 22px}.title-copy h1 em{color:var(--gold-bright);font-style:normal}.title-lede{font:19px var(--serif);color:#e5dfd1;margin:0 0 14px}.title-desc{color:#999ba8;line-height:1.9;font-size:13px;margin:0 0 35px}.title-buttons{display:flex;align-items:center;gap:20px}.primary-button,.secondary-button{border:0;cursor:pointer;font:600 13px var(--sans);transition:transform .2s,background .2s}.primary-button{background:linear-gradient(110deg,#ddc28b,#c6a567);color:#201c18;padding:14px 22px;box-shadow:0 7px 25px #caa76a22}.primary-button:hover{transform:translateY(-2px);background:#eed7a0}.primary-button span{font-size:18px;margin-left:20px}.text-button{background:none;border:0;color:#bdaf8b;font:12px var(--sans);cursor:pointer;padding:12px}.title-note{color:#6e7180;font-size:10px;margin-top:22px;letter-spacing:.06em}.title-note span{padding:0 8px;color:#b29c70}.game-layout{display:grid;grid-template-columns:240px minmax(420px,1fr) 165px;gap:26px;padding:31px 0 44px;align-items:start}.hidden{display:none!important}.panel{background:var(--panel);border:1px solid var(--line);box-shadow:0 14px 40px #06080d33;backdrop-filter:blur(14px)}.sidebar{display:flex;flex-direction:column;gap:14px}.character-card{padding:18px 17px 17px}.character-top{display:flex;align-items:center;gap:12px;margin-bottom:19px}.avatar{height:42px;width:42px;border-radius:50%;border:1px solid #c9b17977;background:radial-gradient(circle,#4a4965,#1e2231 70%);display:grid;place-items:center;color:#e6d39e;font-size:22px}.muted-label{color:#858897;font-size:9px;letter-spacing:.12em}.character-top h2{font:17px var(--serif);margin:3px 0}.character-top p{color:#c1b590;font-size:10px;margin:0}.resource{margin:13px 0}.resource-label{display:flex;justify-content:space-between;color:#a8a9b2;font-size:10px;margin-bottom:7px}.resource-label b{color:#e2ddd1;font-weight:500}.meter,.level-progress{height:5px;border-radius:5px;background:#373947;overflow:hidden}.meter i,.level-progress i{display:block;height:100%;width:100%;background:linear-gradient(90deg,#bd6d6c,#d79683);border-radius:5px;transition:width .4s}.mana-resource .meter i{background:linear-gradient(90deg,#7673be,#aaa3e8)}.character-stats{display:grid;grid-template-columns:repeat(3,1fr);padding-top:10px;margin-top:16px;border-top:1px solid var(--line)}.character-stats div{display:flex;flex-direction:column;gap:3px}.character-stats span{color:#777b8a;font-size:9px}.character-stats b{font-size:12px;color:#e8dfcd;font-weight:500}.level-progress{height:3px;margin-top:10px}.level-progress i{background:#d7b979;width:0}.quest-panel,.inventory-panel{padding:15px 17px}.panel-heading{display:flex;align-items:center;justify-content:space-between;color:#898c9a;font-size:10px;letter-spacing:.1em}.quest-icon{font-size:16px;color:var(--gold)}.quest-panel h3{font:15px var(--serif);margin:13px 0 7px;color:#e7dfd1}.quest-panel p{font-size:10px;line-height:1.7;color:#999ba8;margin:0;min-height:34px}.quest-status{margin-top:13px;color:#a6c3a6;font-size:9px}.quest-status .status-dot{width:5px;height:5px}.gold-count{color:#d8b979;font-size:11px;letter-spacing:0}.gold-count b{font-weight:500}.inventory-list{display:flex;flex-direction:column;gap:9px;margin-top:14px}.inventory-item{display:flex;align-items:center;gap:8px;color:#bcbac0;font-size:10px}.item-icon{width:20px;height:20px;border:1px solid #ffffff12;background:#ffffff06;display:grid;place-items:center;color:#d8b979;font-size:11px}.item-count{margin-left:auto;color:#777b88}.inventory-empty{font-size:10px;color:#777b88;padding:3px 0}.journal-button{height:40px;border:1px solid var(--line);background:#1b1e29;color:#c6c2b9;text-align:left;padding:0 13px;cursor:pointer;font:11px var(--sans)}.journal-button>span:first-child{color:var(--gold);font-size:15px;margin-right:8px}.journal-count{float:right;color:#888b98}.story-column{min-width:0}.location-bar{display:flex;align-items:center;gap:9px;height:31px;color:#ddd5c5;font:12px var(--serif);margin:0 3px 12px}.location-pin{color:var(--gold);font-size:18px}.location-line{height:1px;flex:1;background:linear-gradient(90deg,var(--line),transparent);margin:0 8px}.location-bar #day-label{font:10px var(--sans);color:#818491}.story-card{overflow:hidden}.scene-art{height:192px;position:relative;overflow:hidden;background:radial-gradient(ellipse at 50% 56%,#5f5974,#302e44 42%,#1d2131 76%)}.scene-art:after{content:'';position:absolute;bottom:0;left:0;right:0;height:45%;background:linear-gradient(160deg,transparent 15%,#141925 16%);clip-path:polygon(0 63%,23% 42%,46% 67%,68% 27%,100% 56%,100% 100%,0 100%);opacity:.95}.scene-art:before{z-index:1}.scene-orb{position:absolute;width:92px;height:92px;left:calc(50% - 46px);top:35px;border-radius:50%;background:radial-gradient(circle at 38% 32%,#fff8d8,#d6c8a6 49%,#b1a4ac 76%);box-shadow:0 0 25px #dfcfaa88,0 0 72px #9995d766}.scene-symbol{position:absolute;z-index:2;right:8%;top:13%;color:#e3d3a9;font-size:16px;text-shadow:0 0 15px #fff}.scene-landscape{position:absolute;bottom:0;left:0;right:0;height:48%;background:#232738;clip-path:polygon(0 46%,11% 22%,22% 59%,37% 5%,51% 51%,70% 22%,84% 61%,100% 18%,100% 100%,0 100%)}.story-content{padding:24px 31px 17px}.story-kicker{font-size:9px;letter-spacing:.2em;color:var(--gold);margin-bottom:8px}.story-content h2{font:24px var(--serif);font-weight:400;margin:0 0 15px;color:#f0eadd}.story-text{color:#c1c0c3;font:13px/1.95 var(--serif);white-space:pre-line}.story-text p{margin:0 0 11px}.story-text em{font-style:normal;color:var(--gold-bright)}.choice-list{display:flex;flex-direction:column;gap:8px;margin-top:20px}.choice-button{width:100%;text-align:left;background:rgba(255,255,255,.025);border:1px solid rgba(220,204,165,.13);padding:12px 14px;color:#dedbd4;font:12px var(--sans);cursor:pointer;transition:.2s;display:flex;align-items:center;gap:11px;line-height:1.5}.choice-button:before{content:'◇';color:var(--gold);font-size:14px}.choice-button:hover{background:#d6bd7e12;border-color:#cfb87966;transform:translateX(3px);color:#fff}.choice-button:disabled{opacity:.42;cursor:not-allowed;transform:none}.choice-note{font-size:9px;color:#8e8d92;margin-left:auto;white-space:nowrap}.story-footer{border-top:1px solid var(--line);display:flex;gap:10px;align-items:center;color:#777b89;font-size:9px;margin-top:22px;padding-top:12px}.story-footer span:nth-child(2){font-size:8px;color:var(--gold)}.bottom-hint{text-align:center;color:#696d7b;font-size:9px;padding:13px}.bottom-hint span{color:#b4a577;font-size:12px;margin-right:7px}.right-rail{padding:5px 0 0}.rail-heading{font-size:10px;color:#a7a5a0;letter-spacing:.12em;padding-bottom:15px;border-bottom:1px solid var(--line)}.timeline{position:relative;padding:16px 0 0 14px}.timeline:before{content:'';position:absolute;left:3px;top:20px;bottom:7px;width:1px;background:#393a44}.timeline-item{position:relative;margin:0 0 17px;color:#a4a4ab;font-size:10px;line-height:1.55}.timeline-item:before{content:'';position:absolute;left:-14px;top:4px;width:6px;height:6px;border-radius:50%;background:#77798a;border:2px solid #171a24}.timeline-item.active{color:#e0d5b9}.timeline-item.active:before{background:var(--gold);box-shadow:0 0 9px #dbbd78}.timeline-item small{display:block;color:#6f7380;font-size:9px;margin-top:3px}.rail-quote{border-top:1px solid var(--line);padding-top:15px;margin-top:26px;color:#a49d90;font:11px/1.8 var(--serif);font-style:italic}.rail-quote span{display:block;text-align:right;color:#70727f;font:9px var(--sans);margin-top:8px}.dice-result{border-left:2px solid var(--gold);background:#d7b9790d;padding:10px 13px;margin-top:17px;color:#c9c0ad;font-size:11px;line-height:1.7}.dice-result strong{color:var(--gold-bright)}.combat-ui{margin-top:18px}.enemy-card{padding:13px 14px;border:1px solid #b4777760;background:#6d343414;display:grid;grid-template-columns:1fr auto;gap:8px;align-items:center}.enemy-name{font:15px var(--serif);color:#efc5b8}.enemy-desc{font-size:9px;color:#9b8990;margin-top:4px}.enemy-hp{font-size:10px;color:#d4a9a0;text-align:right}.enemy-meter{height:4px;background:#492f35;grid-column:1/-1}.enemy-meter i{display:block;height:100%;background:#c66f66;transition:width .3s}.combat-actions{display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-top:11px}.combat-actions .choice-button{padding:11px 10px}.combat-actions .choice-button:before{font-size:13px}.combat-log{font:11px/1.7 var(--serif);color:#aaa7a4;min-height:25px;margin-top:10px}.toast{position:fixed;left:50%;bottom:25px;z-index:10;transform:translate(-50%,20px);padding:11px 18px;background:#272a36;border:1px solid #bba67566;color:#eddfbd;font-size:11px;opacity:0;pointer-events:none;transition:.3s;box-shadow:0 12px 35px #0008}.toast.show{opacity:1;transform:translate(-50%,0)}.modal-backdrop{position:fixed;inset:0;z-index:20;background:#080a10c9;display:grid;place-items:center;padding:20px}.modal{position:relative;width:min(510px,100%);padding:30px}.modal-close{position:absolute;right:18px;top:14px;background:none;border:0;color:#aaa;font-size:24px;cursor:pointer}.modal h2{font:25px var(--serif);margin:0 0 20px}.journal-entries{max-height:45vh;overflow:auto}.journal-entry{border-left:1px solid #bda36d;padding:0 0 15px 15px;margin-left:4px;position:relative}.journal-entry:before{content:'';position:absolute;left:-4px;top:3px;width:7px;height:7px;border-radius:50%;background:#d5b976}.journal-entry h3{font:14px var(--serif);margin:0 0 5px;color:#e1d3b1}.journal-entry p{font-size:11px;color:#9fa0a8;line-height:1.7;margin:0}.modal-actions{display:flex;gap:10px;justify-content:flex-end;margin-top:22px}.secondary-button{background:transparent;border:1px solid #ffffff22;color:#b2b0b3;padding:11px 14px}.secondary-button:hover{border-color:#b67d78;color:#e5b7ad}
@media(max-width:1100px){main{padding:0 3%}.game-layout{grid-template-columns:215px minmax(350px,1fr);gap:20px}.right-rail{display:none}.title-screen{gap:5%}}
@media(max-width:720px){.topbar{height:62px;padding:0 17px}.brand{font-size:16px}.brand-mark{font-size:21px}.chapter-label{display:none}.top-actions{gap:9px}.icon-button{width:30px;height:30px}main{padding:0 14px}.title-screen{min-height:calc(100svh - 62px);display:flex;flex-direction:column;justify-content:center;gap:25px;padding:25px 0 35px}.title-art{width:100%;height:32vh;min-height:220px;max-height:300px;order:0}.moon{width:105px;height:105px;left:calc(50% - 52px);top:18%}.moon:after{width:105px;height:105px;left:12px}.title-copy{padding:0 6px;order:1}.eyebrow{margin-bottom:12px;font-size:9px}.title-copy h1{font-size:55px;margin-bottom:13px}.title-lede{font-size:16px}.title-desc{font-size:12px;margin-bottom:22px}.title-note{margin-top:16px}.game-layout{display:flex;flex-direction:column;padding:17px 0 32px;gap:12px}.story-column{order:1;width:100%}.sidebar{order:2;width:100%;display:grid;grid-template-columns:1fr 1fr;gap:10px}.character-card{grid-column:1/-1;padding:13px 14px}.character-top{margin-bottom:12px}.character-top .avatar{width:38px;height:38px}.resource{margin:9px 0}.character-stats{margin-top:11px;padding-top:9px}.quest-panel,.inventory-panel{padding:13px}.quest-panel p{min-height:48px}.journal-button{grid-column:1/-1}.location-bar{margin:0 2px 9px;height:26px}.story-card{border-left:0;border-right:0}.scene-art{height:153px}.scene-orb{width:70px;height:70px;left:calc(50% - 35px);top:29px}.story-content{padding:19px 17px 15px}.story-content h2{font-size:21px}.story-text{font-size:12px;line-height:1.9}.choice-button{padding:11px 10px;font-size:11px}.choice-note{font-size:8px}.story-footer{margin-top:18px}.bottom-hint{padding:10px}.combat-actions{gap:6px}.combat-actions .choice-button{font-size:10px;padding:10px 7px}.modal{padding:25px 20px}.modal-actions{flex-wrap:wrap}.modal-actions button{flex:1}.title-art{flex-shrink:0}}
@media(max-width:380px){main{padding:0 10px}.sidebar{gap:8px}.quest-panel,.inventory-panel{padding:11px}.story-content{padding-left:13px;padding-right:13px}.title-copy h1{font-size:48px}}

const $ = (id) => document.getElementById(id);
const SAVE_KEY = 'star_echoes_save_v1';
const initialState = () => ({scene:'awakening',hp:24,maxHp:24,mp:12,maxMp:12,atk:5,def:2,level:1,exp:0,gold:8,inventory:[{id:'potion',name:'작은 회복약',icon:'⚗',count:2}],flags:{},log:[],day:'첫째 날 · 새벽',location:'경계의 숲',combat:null,combatContext:null,visited:[]});
let state = initialState();
const scenes = {
 awakening:{kicker:'PROLOGUE · REBIRTH',title:'별빛 아래에서',location:'경계의 숲',day:'첫째 날 · 새벽',text:'눈을 뜨자, 낯선 별들이 내려다보고 있었다.\n\n방금 전까지 분명 비 내리는 횡단보도에 서 있었는데. 지금은 젖은 이끼의 냄새와, 숲 사이로 떠오른 거대한 푸른 달이 전부다. 손바닥에는 희미하게 빛나는 문양이 새겨져 있다.\n\n그때, 나뭇가지 위에서 작은 목소리가 들렸다. <em>“드디어 왔구나, 길을 건너온 사람아.”</em>',choices:[
  {label:'푸른 불빛을 따라간다',note:'운명의 주사위',roll:'지혜',action:()=>{const r=dice();state.flags.memory=r>=4;state.mp=Math.min(state.maxMp,state.mp+2);addItem('potion',1);toast(r>=4?'기억의 파편을 떠올렸다 · 회복약 +1':'희미한 기억만 스쳤다 · 회복약 +1');go('companion');}},
  {label:'먼저 주변을 살피고 목소리의 주인을 찾는다',note:'신중한 시작',action:()=>{state.def+=1;state.flags.cautious=true;go('companion','숲의 기척을 읽었다. 수호가 1 상승했다.');}},
  {label:'“여기가 어디야?” 하고 당당히 외친다',note:'낯선 세계에 맞선다',action:()=>{state.atk+=1;state.flags.bold=true;go('companion','두려움을 삼키고 앞으로 나아갔다. 공격이 1 상승했다.');}}
 ]},
 companion:{kicker:'CHAPTER I · THE CALL',title:'나뭇가지 위의 안내자',location:'경계의 숲',day:'첫째 날 · 아침',text:'잎사귀 사이에서 날개 달린 작은 여우가 나타났다. 꼬리 끝에는 별가루가 반짝인다.\n\n<em>“나는 루. 네가 건너온 틈새를 지키는 안내자야. 이 숲의 북쪽에 있는 별의 신전으로 가야 해. 균열이 커지기 전에.”</em>\n\n루가 앞발로 가리킨 곳에는 어둠 속에서 떨고 있는 어린 여행자가 있다. 숲의 그림자가 그 아이를 에워싸고 있다.',choices:[
  {label:'루와 함께 아이를 구하러 간다',note:'동료 루 합류',action:()=>{state.flags.lu=true;state.flags.savedChild=true;state.atk+=1;state.log.push({title:'작은 안내자 루',text:'위험에 처한 아이를 구하고 루와 함께하기로 했다. 루의 용기로 공격이 1 상승했다.'});go('fork','루가 동료가 되었다.');}},
  {label:'먼저 그림자의 정체를 확인한다',note:'관찰 판정',roll:'통찰',action:()=>{state.flags.lu=true;state.flags.observed=true;const r=dice();if(r>=4){state.gold+=5;toast('숨겨진 주머니 발견 · 금화 +5');}else toast('그림자가 가까워졌다.');go('fork');}},
  {label:'아이를 구하기 위해 혼자 달려든다',note:'용기 판정',roll:'용기',action:()=>{state.flags.lu=true;state.flags.wounded=true;state.hp=Math.max(16,state.hp-3);state.log.push({title:'숲의 그림자',text:'다치긴 했지만 아이를 무사히 구했다. 루가 동행한다.'});go('fork','상처를 입었다. 생명력 -3.');}}
 ]},
