13:   {label:'먼저 그림자의 정체를 확인한다',note:'관찰 판정',roll:'통찰',action:r=>{state.flags.lu=true;state.flags.observed=true;if(r>=4){state.gold+=5;toast('숨겨진 주머니 발견 · 금화 +5');}else toast('그림자가 가까워졌다.');go('fork');}},
