import { spawn } from 'node:child_process';
import { setTimeout as delay } from 'node:timers/promises';
const port = 9228;
const profile = `/tmp/opencode/chrome-${process.pid}`;
const browser = spawn('/usr/bin/chromium', ['--headless=new','--no-sandbox','--disable-gpu',`--remote-debugging-port=${port}`,`--user-data-dir=${profile}`,'about:blank'], { stdio:'ignore' });
let socket;
try {
  let targets;
  for (let i=0;i<60;i++) {
    try { targets=await (await fetch(`http://127.0.0.1:${port}/json/list`)).json(); if(targets)break; } catch {}
    await delay(200);
  }
  if(!targets) throw new Error('Chromium debugging endpoint did not start');
  const target=targets.find(t=>t.type==='page');
  socket=new WebSocket(target.webSocketDebuggerUrl);
  await new Promise((resolve,reject)=>{socket.onopen=resolve;socket.onerror=reject;});
  let id=0; const pending=new Map();
  socket.onmessage=event=>{const message=JSON.parse(event.data);if(message.id&&pending.has(message.id)){pending.get(message.id)(message);pending.delete(message.id);}};
  const cdp=(method,params={})=>new Promise(resolve=>{const requestId=++id;pending.set(requestId,resolve);socket.send(JSON.stringify({id:requestId,method,params}));});
  await cdp('Page.enable'); await cdp('Runtime.enable');
  const evaluate=async expression=>{const result=await cdp('Runtime.evaluate',{expression,returnByValue:true,awaitPromise:true});if(result.error)throw new Error(JSON.stringify(result.error));if(result.result.exceptionDetails)throw new Error(result.result.exceptionDetails.text);return result.result.result.value;};
  const clickText=async (selector,text)=>{const found=await evaluate(`(()=>{const b=[...document.querySelectorAll(${JSON.stringify(selector)})].find(x=>x.textContent.includes(${JSON.stringify(text)}));if(!b)throw Error('Missing button: '+${JSON.stringify(text)});b.click();return true})()`);return found;};
  await cdp('Page.navigate',{url:`file://${process.cwd()}/index.html`});
  await delay(500);
  await clickText('#begin-button','새로운 여정');
  await clickText('#choice-list button','푸른 불빛을 따라간다');
  await clickText('#choice-list button','루와 함께 아이를 구하러 간다');
  await clickText('#choice-list button','동쪽 오솔길');
  await clickText('#choice-list button','여행 지도를 펼쳐');
  await clickText('#choice-list button','푸른돛 항구로 간다');
  let status=await evaluate(`({scene:document.querySelector('#story-title').textContent,day:document.querySelector('#day-label').textContent})`);
  if(status.scene!=='푸른돛 항구')throw new Error(`Unexpected scene ${JSON.stringify(status)}`);
  await clickText('#choice-list button','어부들과 그물을 손질한다');
  status=await evaluate(`({scene:document.querySelector('#story-title').textContent,day:document.querySelector('#day-label').textContent})`);
  if(!status.day.includes('3일째'))throw new Error(`Work did not advance day: ${JSON.stringify(status)}`);
  await clickText('#choice-list button','여행 지도로 다른 마을을 고른다');
  await clickText('#choice-list button','달맞이 고개 마을로 간다');
  await clickText('#choice-list button','약초밭 일을 도와');
  status=await evaluate(`({scene:document.querySelector('#story-title').textContent,day:document.querySelector('#day-label').textContent, inventory:document.querySelector('#inventory-list').textContent})`);
  if(status.scene!=='달맞이 고개 마을'||!status.day.includes('5일째')||!status.inventory.includes('×3'))throw new Error(`Highland work/date/inventory failed: ${JSON.stringify(status)}`);
  await clickText('#save-button','');
  await cdp('Page.reload',{ignoreCache:true}); await delay(500);
  await clickText('#continue-button','');
  status=await evaluate(`({scene:document.querySelector('#story-title').textContent,day:document.querySelector('#day-label').textContent,inventory:document.querySelector('#inventory-list').textContent})`);
  if(status.scene!=='달맞이 고개 마을'||!status.day.includes('5일째')||!status.inventory.includes('×3'))throw new Error(`Save/load failed: ${JSON.stringify(status)}`);
  console.log('Browser flow passed:',JSON.stringify(status));
} finally { try{socket?.close();}catch{} browser.kill('SIGTERM'); }
